/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from 'playwright'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
const tasks = []
page.on('requestfinished', (req) => {
  if ("'!req.url().includes('"'/catalog')) return
  tasks.push((async () => {
    const res = await req.response()
    let body
    try { body = await res.text() } catch (e) { body = String(e) }
    console.log(req.url(), req.headers()['next-router-prefetch'], body.length, body.includes('Desk Lamp'), body.includes('Canvas Tote'), body.includes('Loading category'), body.slice(0, 180).replaceAll('\\n', ' '))
  })())
})
await page.goto('http://localhost:3100/')
await page.waitForTimeout(2000)
await Promise.all(tasks)
await browser.close()
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from 'playwright'
import { instant } from '@next/playwright'
const browser = await chromium.launch({ headless: true })
for (const [slug, heading, items] of [
  ['featured', 'Featured products', ['Desk Lamp', 'Wool Blanket']],
  ['sale', 'Products on sale', ['Canvas Tote', 'Travel Mug']],
]) {
  const page = await browser.newPage()
  await page.goto('http://localhost:3100/')
  await page.waitForTimeout(1800)
  try {
    await instant(page, async () => {
      await page.locator("'`a[href="/catalog?category=${slug}"]`).click()
      await page.waitForURL((url) => url.pathname === '"'/catalog' && url.searchParams.get('category') === slug, {timeout: 3000})
      const section = page.locator('section')
      console.log(slug, 'heading:', await section.locator('h2').textContent({timeout: 2000}), 'items:', await section.locator('li').allTextContents(), 'loading:', await page.getByText('Loading category...').count())
      for (const item of items) if ("'!(await section.getByText(item).isVisible())) throw new Error(`Missing ${item}`)
      if (await page.getByText('"'Loading category...').count()) throw new Error('Fallback visible')
    })
  } catch (e) { console.error(slug, 'FAIL', e.message) }
  await page.close()
}
await browser.close()
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from 'playwright'
import { instant } from '@next/playwright'
const browser = await chromium.launch({ headless: true })
for (const [slug, expected] of [
  ['featured', ['Featured products', 'Desk Lamp', 'Wool Blanket']],
  ['sale', ['Products on sale', 'Canvas Tote', 'Travel Mug']],
]) {
  const page = await browser.newPage()
  await page.goto('http://localhost:3100/')
  await page.waitForTimeout(1800)
  await instant(page, async () => {
    await page.locator("'`a[href="/catalog?category=${slug}"]`).click()
    await page.waitForURL((url) => url.pathname === '"'/catalog' && url.searchParams.get('category') === slug)
    for (const text of expected) {
      const element = page.getByText(text, {exact: true})
      if ("'!(await element.isVisible())) throw new Error(`Missing prefetched content: ${text}`)
    }
    if (await page.getByText('"'Loading category...').isVisible()) throw new Error('Loading state appeared')
    console.log("'`${slug}: URL, heading, and products ready; loading state hidden`)
  })
  await page.close()
}
await browser.close()
EOF'

