    await page.locator("'`a[href="/catalog?category=${slug}"]`).click()
    await page.waitForURL((url) => url.pathname === '"'/catalog' && url.searchParams.get('category') === slug)
    if ("'!(await page.getByRole('"'heading', {name: heading, level: 2}).isVisible())) throw new Error("'`Missing ${heading}`)
    for (const item of items) {
      if (!(await page.locator('"'section li').getByText(item, {exact: true}).isVisible())) throw new Error("'`Missing ${item}`)
    }
